        "v": "Ремни передних сидений имеют регулировку положения верхней точки крепления по высоте. Слегка вытянув ремень, отрегулируйте его высоту так, чтобы он располагался как можно выше, но не касался шеи и не давил на плечо. Для регулировки прижмите к стойке декоративную накладку ремня 1 (рис. 16) и, перемещая ее, выберите одно из пяти фиксированных положений крепления верхней точки по высоте."
