        "v": "Не допускается чистка спирали подвижной части прикуривателя металлическими предметами, это может привести к ее повреждению. При замене необходимо использовать только типы прикуривателей, которые рекомендованы для данного автомобиля и только тех производителей, которые имеют заключение ПАО «АВТОВАЗ». Патрон для подключения дополнительного электрооборудования (или патрон прикуривателя, в зависимости от комплектации) может быть дополнительно использован для подключения только 12-вольтовых электрических приборов мощностью не более 120 Вт. Перегрузка патрона может привести к короткому замыканию. Не используйте более одного электрического прибора. Если вилка электрического прибора слишком свободно или слишком плотно размещается в патроне прикуривателя, это может привести к плохому контакту или к застреванию вилки. Используйте электрические приборы только с соответствующими вилками (разъемами), которые указаны на рисунке 23в. Не оставляйте подключенные к патрону электроприборы, если водитель и пассажиры покидают салон автомобиля или автомобиль ставится на длительную стоянку.",
