          "Если обнаружен дефектный датчик или другая неисправность, после сигнала включения раздается непрерывный звуковой сигнал низкого тона в течение 3 секунд. Затем система укажет неисправный датчик: один короткий сигнал — левый датчик, два — центральный, три — правый. Если неисправен блок управления, раздается сигнал низкого тона длительностью около 2 секунд. После сигнализации о наличии неисправности система отключается.",
