        "v": "Периодически проверяйте давление воздуха в шинах манометром. Эксплуатация шин с давлением, отличающимся от рекомендованного, приводит к их преждевременному износу, ухудшению устойчивости и управляемости автомобиля, а также к увеличению расхода топлива."
