        "v": "В пульте дистанционного управления содержится литиевый элемент питания типа CR2032, начальное напряжение питания которого 3 В. Если напряжение питания пульта находится в пределах нормы, то при каждом нажатии на любую кнопку пульта индикатор пульта загорается короткой вспышкой. Если при нажатии на любую кнопку пульта индикатор загорается двумя короткими вспышками или не загорается вообще, то следует заменить элемент питания на новый. Для этого проделайте следующие действия:"
